import json
import os
import sys
from collections import defaultdict

sys.path.insert(0, "/workspace/suite")
import bench  # noqa: E402

items = bench.build_all()
by_dom = defaultdict(lambda: defaultdict(list))
for it in items:
    by_dom[it["domain"]][it["family"]].append(it["id"])

weights = {}
for dom, fams in by_dom.items():
    w = {}
    nf = len(fams)
    for fam, ids in fams.items():
        for i in ids:
            w[i] = round(1.0 / (nf * len(ids)), 8)
    weights[dom] = w

path = "/workspace/suite/assets/domain_weights.json"
json.dump(weights, open(path, "w"), indent=1)
print({d: (len(w), round(sum(w.values()), 6)) for d, w in weights.items()})
